      localDanmuElement('span', 'local-danmu-group-title', group.title),
      localDanmuElement('span', 'local-danmu-group-meta', (group.year || '\u5E74\u4EFD\u672A\u586B\u5199') + ' \xB7 ' + (typeNames[group.type] || group.type || '\u7C7B\u578B\u672A\u586B\u5199') + seasonText),
      localDanmuElement('span', 'local-danmu-group-count', '\u5DF2\u4E0A\u4F20 ' + group.episodeCount + (group.type === 'movie' ? ' \u4E2A\u6587\u4EF6 \xB7 ' : ' \u96C6 \xB7 ') + Number(group.count || 0).toLocaleString() + ' \u6761\u5F39\u5E55')
