  if (isBatch && type !== 'tv') { s.textContent = '\u6279\u91CF\u5BFC\u5165\u7528\u4E8E\u540C\u4E00\u90E8\u7535\u89C6\u5267\uFF0C\u8BF7\u9009\u62E9 tv \u7C7B\u578B\uFF1B\u7535\u5F71\u8BF7\u9010\u4E2A\u4E0A\u4F20\u3002'; return; }
